#!/usr/bin/env node
/**
 * Write the committed book snapshot from the local overlay.
 *
 *   node scripts/write-book-snapshot.mjs
 *
 * Reads data/supabase-book.local.json and writes src/lib/book-snapshot.ts.
 *
 * A TS module rather than a JSON file under data/ for two reasons: data/ is
 * gitignored, and a file read at runtime is not reliably present in Next's
 * standalone output, whereas a module is bundled.
 *
 * This puts real customer data in git. That is a deliberate, reversible
 * decision for an instance that holds no Harper credentials — see the
 * header the generated file carries.
 */

import fs from "node:fs";
import path from "node:path";
import { gzipSync } from "node:zlib";

const BOOK = path.join(process.cwd(), "data", "supabase-book.local.json");
const OUT = path.join(process.cwd(), "src", "lib", "book-snapshot.ts");

if (!fs.existsSync(BOOK)) {
  console.error(`No book at ${BOOK}. Run scripts/import-harper-book.ts first.`);
  process.exit(1);
}

const json = fs.readFileSync(BOOK, "utf-8");
const book = JSON.parse(json);
const b64 = gzipSync(Buffer.from(json, "utf-8"), { level: 9 }).toString("base64");

const accounts = book.accounts?.length ?? 0;
const policies = book.policies?.length ?? 0;
const scheduled = Object.values(book.schedules ?? {}).filter(
  (s) => (s.limits ?? []).length > 0,
).length;

// 96 chars keeps the file diffable-ish and inside sane line-length limits.
const lines = (b64.match(/.{1,96}/g) ?? []).map((c) => `  "${c}",`).join("\n");

const contents = `/**
 * A snapshot of the real book, committed so an instance holding no Harper
 * credentials still serves real accounts instead of the fictional seed.
 *
 * ${accounts} accounts · ${policies} policies · ${scheduled} with limits
 * Captured ${new Date().toISOString().slice(0, 10)} from \`data policy-state read --in-force-only\`.
 *
 * THIS IS REAL CUSTOMER DATA, IN GIT. Gzipped and base64'd, so it is opaque
 * in a diff, but it is the book: company names, policy numbers, carriers,
 * terms and limits. It carries no addresses, contacts, or anything the
 * export's PII floor excludes. It is here because the alternative was a
 * deployed desk that looks like a demo.
 *
 * It is last in line. \`data/supabase-book.local.json\` wins, then
 * \`HARPER_BOOK_B64*\`, then this, then the seed — so local development and
 * a configured deployment both override it without touching this file.
 *
 * To refresh:  npx tsx --conditions react-server scripts/import-harper-book.ts
 *              node scripts/write-book-snapshot.mjs
 * To remove:   delete this file's export body and return "" — the loader
 *              falls through to the seed.
 *
 * Prefer \`POST /api/book/sync\` over refreshing this: with Agent Tools
 * credentials the desk reads the live book and nothing needs committing.
 *
 * Generated by scripts/write-book-snapshot.mjs — do not edit by hand.
 */

const CHUNKS: string[] = [
${lines}
];

/** Gzipped, base64 book JSON. Empty string means no snapshot. */
export const BOOK_SNAPSHOT_B64 = CHUNKS.join("");
`;

fs.writeFileSync(OUT, contents);
console.log(`${accounts} accounts · ${policies} policies · ${scheduled} with limits`);
console.log(`${b64.length} bytes of base64 → ${OUT}`);
